import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"Former af HRT","description":"","frontmatter":{},"headers":[],"relativePath":"formerafhrt.md","filePath":"formerafhrt.md"}`),a={name:`formerafhrt.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="former-af-hrt" tabindex="-1">Former af HRT <a class="header-anchor" href="#former-af-hrt" aria-label="Permalink to “Former af HRT”">​</a></h1><h2 id="østradiol" tabindex="-1">Østradiol <a class="header-anchor" href="#østradiol" aria-label="Permalink to “Østradiol”">​</a></h2><p>Der findes mange former for østradiol, som hver især har deres fordele og ulemper samt varierende grad af tilgængelighed.</p><h3 id="piller" tabindex="-1">Piller <a class="header-anchor" href="#piller" aria-label="Permalink to “Piller”">​</a></h3><p>Piller er den mest populære og kendte løsning, og de er nemme at få fat i, hvis man laver DIY. Ulempen er, at de kan være forholdsvis dyre. Man kan tage østradiol piller oralt eller via sublingual/bukkal administration. De fleste læger vil anbefale at tage pillerne oralt, to gange om dagen. Én gang om morgenen og én gang om aftenen. Dette resulterer som regel i mere stabile niveauer end sublingual/bukkal administration.</p><p>Sublingual administration betyder, at man placerer pillen under tungen og lader den opløses, mens bukkal indtagelse betyder, at man placerer pillen mellem tandkødet og indersiden af ​​kinden, så den kan opløses. Disse to administrationsformer giver i bund og grund det samme resultat.</p><p>Sublingual/bukkal administration medfører højere maksimale koncentrationer af østradiol i blodet, som hurtigt falder igen. Derfor anbefales det, at sublingual administration sker tre gange dagligt med 8 timers mellemrum.</p><p>Nogle vælger sublingual/bukkal administration da det ikke går igennem leveren, og derfor mener man, at der er mindre risiko for blodpropper, og at det kan give bedre virkning. Der er dog kun anekdotisk evidens for dette og det mangler forskning.</p><h3 id="transdermal" tabindex="-1">Transdermal <a class="header-anchor" href="#transdermal" aria-label="Permalink to “Transdermal”">​</a></h3><p>Transdermal behandling (østradiol påført huden) findes i former som gel, plaster og spray.</p><p>Plastre skiftes typisk en til to gange om ugen og er designet til at afgive en fast dosis østradiol hver dag. De placeres normalt på den nederste del af maven eller den øverste del af ballerne. Bemærk, at der i nogle år har været en global mangel på plastre, så det kan være meget svært og dyrt at skaffe dem via uofficielle kanaler.</p><p>Østrogengel fås typisk i breve eller i en pumpeflasker, der afgiver en fast mængde ved hver brug. Østradiolgel er fremstillet med en alkoholbaseret sammensætning for at øge optagelsen. Den påføres normalt på huden én gang dagligt.</p><p>Sprayprodukter sælges typisk af homebrewers og indeholder østradiol i en alkoholbaseret opløsning, der påføres huden – oftest ved hjælp af en sprayflaske. Spray kan påføres inderlår, underarm eller evt. på scrotum for bedre absorption, da huden der er tyndere.</p><h3 id="injektioner" tabindex="-1">Injektioner <a class="header-anchor" href="#injektioner" aria-label="Permalink to “Injektioner”">​</a></h3><p>Østradiol injektioner er den mest almindelige administrationsform, når det kommer til DIY-hormonbehandling. Injektioner er oftest den mest effektive og billige løsning.</p><p>Østradiol fremstilles normalt i en esterificeret form, så det bliver længere i kroppen. Hvis man injicerede almindelig (ikke-esterificeret) østradiol, ville det nedbrydes meget hurtigt; derfor er al injicerbar østradiol esterificeret. Efter injektionen omdanner kroppen langsomt esteren tilbage til almindelig østradiol, hvilket gør, at stoffet bliver længere i kroppen.</p><p>De mest almindelige østradiol-estere er valerat, cypionat, enantat og undecylat. De har hver især en forskellig halveringstid, hvilket angiver, hvor længe stoffet forbliver i kroppen.</p><h2 id="antiandrogener" tabindex="-1">Antiandrogener <a class="header-anchor" href="#antiandrogener" aria-label="Permalink to “Antiandrogener”">​</a></h2><p>Der findes forskellige antiandrogener, men alle kommer umiddelbart som tabletter, som skal tages oralt.</p><p>De mest kendte antiandrogener er følgende:</p><ul><li>Spironolacton (Spiro)</li><li>Cyproteronacetat (Cyproteron, Cypro)</li></ul><p>Spironolacton er et svagt antiandrogen, men det er samtidig meget sikkert. Almindelige bivirkninger omfatter øget tørst, trang til salt og hyppig vandladning. Spironolacton <strong>anbefales ikke</strong> som førstevalg af antiandrogen på grund af dets svage antiandrogene virkning.</p><p>Cyproteron er et meget effektivt antiandrogen, når det kombineres med østrogen. Høje doser bør undgås på grund af en mere problematisk risikoprofil. Det er vigtigt at holde sig under en bestemt dosis, især fordi cyproteron typisk sælges i doser, der er 4-8 gange højere end de anbefalede doser til transfeminine personer.</p><p>Hvis du er på <a href="https://min.medicin.dk/Medicin/Indholdsstoffer/318" target="_blank" rel="noreferrer">cyproteronacetat</a> er det meget vigtigt, at du især holder øje med dine prolaktinniveauer. Cyproteronacetat har en lille chance for at give <a href="https://en.wikipedia.org/wiki/Prolactinoma" target="_blank" rel="noreferrer">prolaktinom</a>, hvilket er en godartet svulst i hypofysen. Det er ikke en almindelig bivirkning af cyproteronacetat, men hvis dine prolaktinniveauer er meget høje, er det vigtigt at tale med din læge.</p><h2 id="progesteron" tabindex="-1">Progesteron <a class="header-anchor" href="#progesteron" aria-label="Permalink to “Progesteron”">​</a></h2><p>Progesteron er en af de to vigtigste kvindelige kønshormoner. Det er ikke nødvendigt for en god transition, men mange oplever, at det hjælper på brystudvikling, har gode effekter på ens humør og kan øge libido. Det anbefales, at man først starter progesteron, når man har taget østrogen i 6-12 måneder.</p><p>Progesteron kommer umiddelbart som tabletter, men nogle homebrewers sælger også transdermal progesteron. Tabletterne tages enten via oral eller rektal administration. Man mener, at rektal administration af progesteron giver bedre absorption og færre bivirkninger. Hvis taget rektalt, kan det hjælpe at skylle tabletten i lunkent vand, da det gør det lettere for den at opløses. Hvis det ikke er nok, kan du evt. også prikke et lille hul i tabletten med en nål. Det anbefalet at tage pillen, før du skal i seng, da det hjælper at ligge ned bagefter, og fordi der er mindre chance for du skal på toilettet om natten.</p><p>Man tager som regel progesteron én gang om dagen. Hvis det tages oralt, anbefales det at gøre det om aftenen, da mange oplever, at man kan blive meget træt, efter man tager det.</p><h2 id="testosteron" tabindex="-1">Testosteron <a class="header-anchor" href="#testosteron" aria-label="Permalink to “Testosteron”">​</a></h2><p>Der findes flere forskellige former, hver med deres fordele og ulemper samt varierende sværhedsgrad, når det gælder at skaffe dem.</p><h3 id="injektioner-1" tabindex="-1">Injektioner <a class="header-anchor" href="#injektioner-1" aria-label="Permalink to “Injektioner”">​</a></h3><p>Injektioner er den mest populære og tilgængelige metode til DIY-hormonbehandling, da de giver mulighed for den nemmeste og mest ensartede dosering.</p><p>Testosteron fremstilles normalt i en esterificeret form, så det bliver længere i kroppen. Hvis man injicerede rent (ikke-esterificeret) testosteron, ville det nedbrydes meget hurtigt; derfor er alt injicerbart testosteron esterificeret. Efter injektionen omdanner kroppen gradvist esteren tilbage til almindeligt testosteron, hvilket gør, at testosteronet bliver i kroppen i længere tid.</p><p>Almindelige estere omfatter cypionat, enantat og undecanoat. Forskellige estere har forskellige halveringstider (den tid, stoffet bliver i kroppen). Ved samme dosis giver estere med kortere halveringstid højere koncentrationstoppe, men i kortere tid. Estere med længere halveringstid giver lavere toppe og virker i længere tid, samtidig med at de tillader sjældnere injektioner.</p><p>Kort sagt beskriver begrebet &quot;halveringstid&quot;, hvor længe lægemidlet virker i kroppen.</p><h3 id="gel" tabindex="-1">Gel <a class="header-anchor" href="#gel" aria-label="Permalink to “Gel”">​</a></h3><p>Testosterongel er normalt sværere at finde hos forhandlere, men den bliver generelt i mindre grad kontrolleret af toldvæsenet ved bestilling fra udlandet. Testosterongel kan være lige så effektiv som injicerbart testosteron. Det skal typisk påføres huden dagligt. Produktet fås enten i breve eller pumpeflasker.</p><p>Hvis du får testosteronrecepter fra en privat klinik vil det højst sandsynligt være gel.</p>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};